import { EJSON } from 'bson';
import type { Collection, CountDocumentsOptions, Document, Filter, MongoClient, Sort } from 'mongodb';
import type {
  CollectionBulkDeleteItemResult,
  CollectionBulkDeleteResult,
  CollectionBulkUpdateChange,
  CollectionBulkUpdateItemResult,
  CollectionBulkUpdateResult,
  CollectionDocumentsPage,
  CollectionMutationResult,
} from '../../shared/domain/index.js';
import { serializeToEjson } from '../../shared/ejson/index.js';
import { appError, serializeError } from '../../shared/errors/index.js';
import { bulkFieldPathError } from '../../shared/collection-update.js';
import {
  DocumentExpressionError,
  parseDocumentArrayExpression,
  parseDocumentExpression,
  parseValueExpression,
} from '../../features/script-analysis/index.js';
import { CursorRegistry, type CursorOwner } from '../registry/cursors.js';

export interface CollectionNamespace {
  database: string;
  collection: string;
}

export interface CollectionFindOptions extends CollectionNamespace {
  owner: CursorOwner;
  filterEjson: string;
  sortEjson?: string;
  projectionEjson?: string;
  pageSize: number;
  /** Documents to skip before this page (skip/limit paging, ADR-0014). */
  skip?: number;
  /** Query timeout from Settings (CSOT); 0 = no limit. Omitted keeps the 30 s server cap. */
  timeoutMS?: number;
  signal?: AbortSignal;
  onCursorRegistered?: (cursorId: string) => void;
}

export interface CollectionInsertOptions extends CollectionNamespace {
  documentEjson: string;
}

export interface CollectionReplaceOptions extends CollectionNamespace {
  originalDocumentEjson: string;
  documentEjson: string;
}

export interface CollectionDeleteOptions extends CollectionNamespace {
  originalDocumentEjson: string;
}

export interface CollectionBulkUpdateOptions extends CollectionNamespace {
  originalDocumentsEjson: string[];
  change: CollectionBulkUpdateChange;
}

export interface CollectionBulkDeleteOptions extends CollectionNamespace {
  originalDocumentsEjson: string[];
}

export interface CollectionCountOptions extends CollectionNamespace {
  filterEjson: string;
  /** Query timeout from Settings (CSOT); 0 = no limit. Never shortens the count floor. */
  timeoutMS?: number;
}

export interface CollectionRenameOptions extends CollectionNamespace {
  newName: string;
}

export async function findCollectionDocuments(
  client: MongoClient,
  registry: CursorRegistry,
  options: CollectionFindOptions,
): Promise<CollectionDocumentsPage> {
  const filter = parseQueryDocumentExpression(options.filterEjson, 'Filter');
  const sort = options.sortEjson
    ? parseQueryDocumentExpression(options.sortEjson, 'Sort')
    : undefined;
  const projection = options.projectionEjson
    ? parseQueryDocumentExpression(options.projectionEjson, 'Projection')
    : undefined;

  // One page handle per tab. Loading another page or re-applying a filter
  // releases the previous page and its oversized full-value handles.
  await registry.closeAllForOwner(options.owner);

  // ADR-0014: every page is an independent skip/limit query, so no server-side
  // cursor outlives the request (no idle expiry, CSOT lifetime or reconnect loss).
  const skip = Math.max(0, Math.trunc(options.skip ?? 0));
  const collection = client.db(options.database).collection(options.collection);
  const cursor = collection.find(filter as Filter<Document>, {
    ...(projection ? { projection } : {}),
    // Preserve deprecated-but-supported BSON values such as BSON Symbol.
    // Canonical EJSON serialization then carries every type to the renderer
    // without changing the normal driver behavior of user query scripts.
    promoteValues: false,
    sort: stablePageSort(sort),
    ...(skip > 0 ? { skip } : {}),
    // One document beyond the page tells the registry whether another page exists.
    limit: options.pageSize + 1,
    ...(options.timeoutMS === undefined ? { maxTimeMS: 30_000 } : { timeoutMS: options.timeoutMS }),
    ...(options.signal ? { signal: options.signal } : {}),
  });

  const cursorId = registry.register(
    cursor,
    options.owner,
    `${options.database}.${options.collection}`,
  );
  options.onCursorRegistered?.(cursorId);
  try {
    const page = await registry.fetchNext(cursorId, options.pageSize);
    // Keep only the serialized page (full values, current-page export).
    await registry.release(cursorId);
    return {
      ...page,
      pageIndex: Math.floor(skip / options.pageSize),
      cursorId,
      pageSize: options.pageSize,
      skip,
    };
  } catch (error) {
    await registry.close(cursorId);
    throw error;
  }
}

/**
 * Skip/limit pages need a total order: MongoDB does not guarantee the order of
 * equal sort keys, or of an unsorted find, between two queries. `_id` breaks
 * ties (and is the default order); `$natural` cannot be combined with it.
 */
export function stablePageSort(sort: Document | undefined): Sort {
  const fields = sort ? Object.keys(sort) : [];
  if (fields.length === 0) return { _id: 1 };
  if (fields.includes('_id') || fields.includes('$natural')) return sort as Sort;
  return { ...sort, _id: 1 } as Sort;
}

export async function countCollectionDocuments(
  client: MongoClient,
  options: CollectionCountOptions,
): Promise<{ count: number }> {
  const filter = parseQueryDocumentExpression(options.filterEjson, 'Filter');
  const count = await client
    .db(options.database)
    .collection(options.collection)
    .countDocuments(filter as Filter<Document>, countTimeout(options.timeoutMS));
  return { count };
}

// Exact counts on large or weakly indexed filtered collections can take longer
// than the browser page request. Keep this below the default runtime IPC
// ceiling while avoiding the former, surprisingly short 30 second cap.
const COUNT_TIMEOUT_FLOOR_MS = 110_000;

function countTimeout(timeoutMS: number | undefined): CountDocumentsOptions {
  if (timeoutMS === undefined) return { maxTimeMS: COUNT_TIMEOUT_FLOOR_MS };
  // An explicit CSOT value also overrides the shorter client-level default.
  return { timeoutMS: timeoutMS === 0 ? 0 : Math.max(timeoutMS, COUNT_TIMEOUT_FLOOR_MS) };
}

export async function insertCollectionDocument(
  client: MongoClient,
  options: CollectionInsertOptions,
): Promise<CollectionMutationResult> {
  const document = parseEjsonDocument(options.documentEjson, 'Document');
  const result = await client
    .db(options.database)
    .collection(options.collection)
    .insertOne(document);
  return {
    acknowledged: result.acknowledged,
    insertedId: serializeToEjson(result.insertedId),
  };
}

export async function replaceCollectionDocument(
  client: MongoClient,
  options: CollectionReplaceOptions,
): Promise<CollectionMutationResult> {
  const original = parseEjsonDocument(options.originalDocumentEjson, 'Original document');
  const replacement = parseEjsonDocument(options.documentEjson, 'Document');
  assertDocumentIdUnchanged(original, replacement);

  const collection = client.db(options.database).collection(options.collection);
  const result = await collection.replaceOne(optimisticFilter(original), replacement);
  if (result.matchedCount === 0) {
    await throwMutationConflict(collection, original);
  }
  return {
    acknowledged: result.acknowledged,
    matchedCount: result.matchedCount,
    modifiedCount: result.modifiedCount,
  };
}

export async function bulkUpdateCollectionDocuments(
  client: MongoClient,
  options: CollectionBulkUpdateOptions,
): Promise<CollectionBulkUpdateResult> {
  if (options.originalDocumentsEjson.length < 1 || options.originalDocumentsEjson.length > 500) {
    throw appError('Validation', 'Bulk update requires between 1 and 500 original documents.');
  }

  const originals = options.originalDocumentsEjson.map((source, index) => {
    const document = parseEjsonDocument(source, `Original document ${index + 1}`);
    assertDocumentHasId(document, `Original document ${index + 1}`);
    return document;
  });
  assertUniqueDocumentIds(originals, 'Original documents');

  let replacements: Document[] | undefined;
  let fieldValue: unknown;
  let fieldPath: string | undefined;
  if (options.change.kind === 'replace') {
    if (options.change.documentsEjson.length !== originals.length) {
      throw appError('Validation', 'Bulk replacement must contain exactly one document for every original.');
    }
    const parsed = options.change.documentsEjson.map((source, index) => (
      parseEjsonDocument(source, `Replacement document ${index + 1}`)
    ));
    assertUniqueDocumentIds(parsed, 'Replacement documents');
    const byId = new Map(parsed.map((document) => [canonicalDocumentId(document), document]));
    replacements = originals.map((original) => {
      const replacement = byId.get(canonicalDocumentId(original));
      if (!replacement) {
        throw appError('Validation', 'Replacement documents must preserve the original _id set.');
      }
      assertDocumentIdUnchanged(original, replacement);
      return replacement;
    });
  } else {
    assertBulkFieldPath(options.change.path);
    fieldPath = options.change.path.trim();
    if (options.change.operation === 'set') {
      fieldValue = parseEjsonValue(options.change.valueEjson, 'Field value');
    }
  }

  const collection = client.db(options.database).collection(options.collection);
  const items = await mapWithConcurrency(originals, 8, async (original, index) => {
    try {
      const result = options.change.kind === 'replace'
        ? await collection.replaceOne(optimisticFilter(original), replacements![index]!)
        : await collection.updateOne(
          optimisticFilter(original),
          options.change.operation === 'set'
            ? { $set: { [fieldPath!]: fieldValue } }
            : { $unset: { [fieldPath!]: '' } },
        );
      if (!result.acknowledged) {
        throw appError('MongoDBCommand', 'MongoDB did not acknowledge the bulk update item.');
      }
      if (result.matchedCount === 0) await throwMutationConflict(collection, original);
      return {
        index,
        status: 'success',
        modified: result.modifiedCount > 0,
      } satisfies CollectionBulkUpdateItemResult;
    } catch (error) {
      return {
        index,
        status: 'error',
        error: serializeError(error),
      } satisfies CollectionBulkUpdateItemResult;
    }
  });

  const successful = items.filter((item) => item.status === 'success');
  const modifiedCount = successful.filter((item) => item.modified).length;
  return {
    requestedCount: originals.length,
    matchedCount: successful.length,
    modifiedCount,
    unchangedCount: successful.length - modifiedCount,
    failedCount: items.length - successful.length,
    items,
  };
}

export async function deleteCollectionDocument(
  client: MongoClient,
  options: CollectionDeleteOptions,
): Promise<CollectionMutationResult> {
  const original = parseEjsonDocument(options.originalDocumentEjson, 'Original document');
  assertDocumentHasId(original, 'Original document');

  const collection = client.db(options.database).collection(options.collection);
  const result = await collection.deleteOne(optimisticFilter(original));
  if (result.deletedCount === 0) {
    await throwMutationConflict(collection, original);
  }
  return {
    acknowledged: result.acknowledged,
    deletedCount: result.deletedCount,
  };
}

export async function bulkDeleteCollectionDocuments(
  client: MongoClient,
  options: CollectionBulkDeleteOptions,
): Promise<CollectionBulkDeleteResult> {
  if (options.originalDocumentsEjson.length < 1 || options.originalDocumentsEjson.length > 500) {
    throw appError('Validation', 'Bulk delete requires between 1 and 500 original documents.');
  }

  // Parse and validate the complete batch before issuing the first delete. This
  // prevents malformed or duplicate inputs from producing partial writes.
  const originals = options.originalDocumentsEjson.map((source, index) => {
    const document = parseEjsonDocument(source, `Original document ${index + 1}`);
    assertDocumentHasId(document, `Original document ${index + 1}`);
    return document;
  });
  assertUniqueDocumentIds(originals, 'Original documents');

  const collection = client.db(options.database).collection(options.collection);
  const items = await mapWithConcurrency(originals, 8, async (original, index) => {
    try {
      const result = await collection.deleteOne(optimisticFilter(original));
      if (!result.acknowledged) {
        throw appError('MongoDBCommand', 'MongoDB did not acknowledge the bulk delete item.');
      }
      if (result.deletedCount === 0) await throwMutationConflict(collection, original);
      return { index, status: 'success' } satisfies CollectionBulkDeleteItemResult;
    } catch (error) {
      return {
        index,
        status: 'error',
        error: serializeError(error),
      } satisfies CollectionBulkDeleteItemResult;
    }
  });

  const deletedCount = items.filter((item) => item.status === 'success').length;
  return {
    requestedCount: originals.length,
    deletedCount,
    failedCount: items.length - deletedCount,
    items,
  };
}

export async function renameCollection(
  client: MongoClient,
  options: CollectionRenameOptions,
): Promise<{ oldName: string; newName: string }> {
  if (options.newName === options.collection) {
    throw appError('Validation', 'The new collection name must be different.');
  }
  await client
    .db(options.database)
    .collection(options.collection)
    .rename(options.newName, { dropTarget: false });
  return { oldName: options.collection, newName: options.newName };
}

export async function dropCollection(
  client: MongoClient,
  options: CollectionNamespace,
): Promise<{ dropped: boolean }> {
  const dropped = await client.db(options.database).collection(options.collection).drop();
  return { dropped };
}

export async function dropDatabase(
  client: MongoClient,
  database: string,
): Promise<{ dropped: boolean }> {
  const dropped = await client.db(database).dropDatabase();
  return { dropped };
}

export function parseEjsonDocument(ejson: string, label: string): Document {
  let value: unknown;
  try {
    value = parseStrictEjsonDocument(ejson, label);
  } catch (ejsonError) {
    try {
      const parsed = parseDocumentExpression(ejson, label);
      value = EJSON.parse(parsed.json, { relaxed: false });
    } catch (expressionError) {
      const message = expressionError instanceof DocumentExpressionError
        ? expressionError.message
        : `${label} is not valid Extended JSON or MongoDB Shell literal syntax.`;
      throw appError('Validation', message, {
        name: (ejsonError as Error).name,
        causeMessage: (ejsonError as Error).message,
      });
    }
  }
  assertNoExecutableCriteriaOperators(value, label);
  return assertDocumentValue(value, label, 'JSON object');
}

export function parseEjsonValue(ejson: string, label: string): unknown {
  let value: unknown;
  try {
    value = EJSON.parse(ejson, { relaxed: false });
  } catch (ejsonError) {
    try {
      const parsed = parseValueExpression(ejson, label);
      value = EJSON.parse(parsed.json, { relaxed: false });
    } catch (expressionError) {
      const message = expressionError instanceof DocumentExpressionError
        ? expressionError.message
        : `${label} is not valid Extended JSON or MongoDB Shell literal syntax.`;
      throw appError('Validation', message, {
        name: (ejsonError as Error).name,
        causeMessage: (ejsonError as Error).message,
      });
    }
  }
  assertNoExecutableCriteriaOperators(value, label);
  return value;
}

export function parseEjsonDocumentArray(ejson: string, label: string): Document[] {
  let value: unknown;
  try {
    value = EJSON.parse(ejson, { relaxed: false });
  } catch (ejsonError) {
    try {
      const parsed = parseDocumentArrayExpression(ejson, label);
      value = EJSON.parse(parsed.json, { relaxed: false });
    } catch (expressionError) {
      const message = expressionError instanceof DocumentExpressionError
        ? expressionError.message
        : `${label} is not a valid document array.`;
      throw appError('Validation', message, {
        name: (ejsonError as Error).name,
        causeMessage: (ejsonError as Error).message,
      });
    }
  }
  if (!Array.isArray(value)) throw appError('Validation', `${label} must be an array of document objects.`);
  assertNoExecutableCriteriaOperators(value, label);
  return value.map((entry, index) => assertDocumentValue(entry, `${label} entry ${index + 1}`, 'document object'));
}

/** Administration forms intentionally keep their strict Extended JSON boundary. */
export function parseStrictEjsonDocument(ejson: string, label: string): Document {
  let value: unknown;
  try {
    value = EJSON.parse(ejson, { relaxed: false });
  } catch (error) {
    throw appError('Validation', `${label} is not valid Extended JSON.`, {
      name: (error as Error).name,
      causeMessage: (error as Error).message,
    });
  }
  return assertDocumentValue(value, label, 'JSON object');
}

function assertDocumentValue(value: unknown, label: string, kind: string): Document {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw appError('Validation', `${label} must be a ${kind}.`);
  }
  return value as Document;
}

/** Collection browser criteria accept safe JS-style object literals. */
export function parseQueryDocumentExpression(source: string, label: string): Document {
  let json: string;
  try {
    json = parseDocumentExpression(source, label).json;
  } catch (error) {
    if (error instanceof DocumentExpressionError) {
      throw appError('Validation', error.message, {
        hint: `Invalid criteria range: characters ${error.start + 1}-${error.end}.`,
      });
    }
    throw error;
  }

  assertNoExecutableCriteriaOperators(JSON.parse(json) as unknown, label);
  let value: unknown;
  try {
    value = EJSON.parse(json, { relaxed: false });
  } catch (error) {
    throw appError('Validation', `${label} contains invalid Extended JSON data.`, {
      name: (error as Error).name,
      causeMessage: (error as Error).message,
    });
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw appError('Validation', `${label} must be an object literal.`);
  }
  return value as Document;
}

const EXECUTABLE_CRITERIA_OPERATORS = new Set(['$where', '$function', '$accumulator']);

function assertNoExecutableCriteriaOperators(value: unknown, label: string): void {
  if (Array.isArray(value)) {
    for (const item of value) assertNoExecutableCriteriaOperators(item, label);
    return;
  }
  if (typeof value !== 'object' || value === null) return;
  for (const [key, nested] of Object.entries(value)) {
    if (EXECUTABLE_CRITERIA_OPERATORS.has(key)) {
      throw appError(
        'Validation',
        `${label} does not allow the executable MongoDB operator ${key}.`,
      );
    }
    assertNoExecutableCriteriaOperators(nested, label);
  }
}

export function assertDocumentIdUnchanged(original: Document, replacement: Document): void {
  assertDocumentHasId(original, 'Original document');
  assertDocumentHasId(replacement, 'Replacement document');
  if (canonicalValue(original._id) !== canonicalValue(replacement._id)) {
    throw appError('Validation', 'The immutable _id field cannot be changed.');
  }
}

export function assertBulkFieldPath(path: string): void {
  const message = bulkFieldPathError(path);
  if (message) throw appError('Validation', message);
}

function assertDocumentHasId(document: Document, label: string): void {
  if (!Object.hasOwn(document, '_id')) {
    throw appError('Validation', `${label} must include an _id field.`);
  }
}

function canonicalDocumentId(document: Document): string {
  assertDocumentHasId(document, 'Document');
  return canonicalValue(document._id);
}

function assertUniqueDocumentIds(documents: Document[], label: string): void {
  const ids = new Set<string>();
  for (const document of documents) {
    const id = canonicalDocumentId(document);
    if (ids.has(id)) throw appError('Validation', `${label} contain a duplicate _id value.`);
    ids.add(id);
  }
}

function canonicalValue(value: unknown): string {
  return EJSON.stringify(value, undefined, 0, { relaxed: false });
}

function optimisticFilter(original: Document): Filter<Document> {
  assertDocumentHasId(original, 'Original document');
  // Match both identity and the exact originally loaded document. The write is
  // atomic: a concurrent change turns the operation into StaleDocument rather
  // than silently overwriting someone else's update.
  return {
    _id: original._id,
    $expr: { $eq: ['$$ROOT', { $literal: original }] },
  } as Filter<Document>;
}

async function throwMutationConflict(
  collection: Collection<Document>,
  original: Document,
): Promise<never> {
  const existing = await collection.findOne(
    { _id: original._id } as Filter<Document>,
    { projection: { _id: 1 } },
  );
  if (existing) {
    throw appError(
      'StaleDocument',
      'The document changed after it was loaded. Refresh before applying this operation.',
    );
  }
  throw appError('NotFound', 'The document no longer exists.');
}

async function mapWithConcurrency<T, R>(
  values: T[],
  concurrency: number,
  operation: (value: T, index: number) => Promise<R>,
): Promise<R[]> {
  const results = new Array<R>(values.length);
  let nextIndex = 0;
  const workers = Array.from({ length: Math.min(concurrency, values.length) }, async () => {
    while (nextIndex < values.length) {
      const index = nextIndex++;
      results[index] = await operation(values[index]!, index);
    }
  });
  await Promise.all(workers);
  return results;
}
